    def as_int(v, default=0):
        try:
            return int(v)
        except Exception:
            return default

    def pos(v):
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("row", "col"), ("pos_x", "pos_y")):
                if a in v and b in v:
                    xa, yb = v.get(a), v.get(b)
                    if isinstance(xa, (int, float)) and isinstance(yb, (int, float)):
